#[allow(unused_imports)]
use crate::connors::Status::{Live, NeedsData, NotTestable};
use std::sync::OnceLock;

pub const BOOK: &str = "mscvl";
const CONV: &str = "Catalogue only (see status).";
pub static MSCVL: Book = Book { id: BOOK, sys: SYS, fml: &[], conv: CONV, cat: OnceLock::new(), par: OnceLock::new() };
pub fn catalogue() -> Vec<StrategyDef> { MSCVL.catalogue() }
pub fn params(id: &str) -> Option<Vec<ParamDef>> { MSCVL.params(id) }
pub fn run(id: &str, x: &Ctx, from: usize, to: usize, p: &Params) -> Option<Vec<Trade>> { MSCVL.run(id, x, from, to, p) }
pub fn family_of(id: &str) -> Option<(&'static str, &'static str, &'static str)> { MSCVL.family_of(id) }
#[allow(dead_code)]
fn _exec_type_check(e: Exec) -> Exec { e }

