#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn catalogue_is_complete_and_nothing_runs() {
        let c = catalogue();
        assert_eq!(c.len(), SYS.len());
        let mut ids: Vec<&str> = c.iter().map(|d| d.id).collect(); ids.sort(); ids.dedup();
        assert_eq!(ids.len(), SYS.len());
        for s in SYS.iter() { assert!(family_of(s.id).is_some()); assert!(params(s.id).is_none()); }
    }
}
